    "descripcion": "Buen frente con portón de ingreso, con cerramientos de alambrados y mucho verde, arboles y posibilidades múltiples.\nBuen camino de ripio, con acceso directo y cercano por ruta asfaltada a la Autovía Artigas, y por ruta 3 hermanas conexión hacia las ciudades de Villa del Rosario y Santa Ana.\nSolo hay que descubrir las potencialidades de esta propiedad y proyectar su futuro.\nZona de tránsito directo al camping de la ciudad de Chajari.\nTiene pozo de agua."
