    "descripcion": "Emprendimiento ubicado en la principal Av. Leopoldo Zarling esquina calle Beija Flor.\nSolo caminas unos pasos y estas con los pies en el mar!!!\nApartamentos de 2, 3 y 4 suites.\nPiel de vidrio en la fachada, con hall de entrada amoblado y decorado.\nInfraestructura para aire acondicionado y agua caliente.\nSistema de aprovechamiento de agua de lluvia. \nAscensor de alta categoría. \nBox de playas y cocheras. \nBalcón con churrasquera.\nPisos de porcelanatto.\nPuertas laqueadas y terminaciones en yeso.\nPiscina.\nSalón de fiestas.\n4 locales comerciales con entrepiso directos a la Avenida.\n(todos los datos según la incorporadora)"
