    "total_caracteristicas": 15,
    "descripcion": "Impecable propiedad de 2 plantas con muchas comodidades y sólida estructura.\nEn Planta Alta tiene 3 dormitorios y baño, con balcón integrado en las habitaciones del frente.\nEn Planta Baja, living, comedor, hogar y cocina hacen un espacio social completo, con salida a patio, sector quincho y parrilla cubierta.\nTiene gas natural instalado y todos los servicios.\nCalle con adoquines.\nA solo 50 metros de Av. Belgrano y Club Velez Sarsfield. Zona de Bancos, escuelas, centro y mucho más.\nOportunidad de una buena inversión.\nConsulte personalmente en la inmobiliaria."
