    "descripcion": "La propiedad está ubicada en el Bº Estación, a media cuadra del Colegio Marista y cerquita del Centro de la ciudad ya que cruzando el paseo de la vía, estás en calle Sarmiento y Urquiza.\nEl lote tiene 10 metros de frente y bien en la parte posterior tiene una casa terminada y habitable.\nConstrucción de 2 dormitorios, cocina comedor, y baño.\nTiene 76 m² cubiertos.\nMucho espacio en la parte de adelante da lugar a aprovechar los metros con cochera, local comercial, etc.\nConsulte personalmente en la inmobiliaria."
